_CORE_SRC = '# Action format: "{from_node: {to_node: count, ...}}".\n# Payout: "filled_p = capacity_p * orders / max(total_capacity, orders)",\n# with "serving_p = min(units_p at the node, SERVE_LIMIT)" and capacity = serving * 4.\n# Cost: "upkeep(node) = UPKEEP_BASE + UPKEEP_PER_HOP * hops(your_base, node)";\n# units on their own base cost 0; all other units, including excess units, pay upkeep.\n\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 90\nSERVE_LIMIT = 6\nUNIT_CAPACITY = 4\n\n\ndef filled(units, opponent_units, orders):\n    """Exact revenue formula, including its zero-denominator case."""\n    capacity = min(units, SERVE_LIMIT) * UNIT_CAPACITY\n    other_capacity = min(opponent_units, SERVE_LIMIT) * UNIT_CAPACITY\n    denominator = max(capacity + other_capacity, orders)\n    return capacity * orders / denominator if denominator > 0 else 0.0\n\n\ndef margin_value(units, opponent_units, orders):\n    """Score difference, excluding upkeep (opponent upkeep is constant)."""\n    return (filled(units, opponent_units, orders)\n            - filled(opponent_units, units, orders))\n\n\ndef preprocess_map(graph):\n    n = int(graph["nodes"])\n    adjacency = [[] for _ in range(n)]\n    for a, b in graph["links"]:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        distance = [-1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if distance[v] < 0:\n                    distance[v] = distance[u] + 1\n                    queue.append(v)\n        distances.append(distance)\n\n    next_hop = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if source == target:\n                next_hop[source][target] = source\n            elif distances[source][target] > 0:\n                next_hop[source][target] = min(\n                    v for v in adjacency[source]\n                    if distances[v][target] == distances[source][target] - 1\n                )\n    return adjacency, distances, next_hop\n\n\ndef legal_action(have, want, adjacency, distances, next_hop):\n    """Closest-first matching; outgoing availability always uses start positions."""\n    n = len(have)\n    surplus = [max(0, have[v] - want[v]) for v in range(n)]\n    deficit = [max(0, want[v] - have[v]) for v in range(n)]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t] and distances[s][t] > 0\n    )\n    proposed = {}\n    for _, source, target in pairs:\n        count = min(surplus[source], deficit[target])\n        if count <= 0:\n            continue\n        hop = next_hop[source][target]\n        surplus[source] -= count\n        deficit[target] -= count\n        key = (source, hop)\n        proposed[key] = proposed.get(key, 0) + count\n\n    action = {}\n    available = list(have)\n    for (source, target), count in sorted(proposed.items()):\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        if target not in adjacency[source] or source == target:\n            continue\n        count = min(int(count), int(available[source]))\n        if count <= 0:\n            continue\n        available[source] -= count\n        action.setdefault(int(source), {})[int(target)] = int(count)\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.previous_want = None\n        self.bad_reports = 0\n\n    def plan(self, obs, deadline):\n        adjacency, distances, next_hop = self.map_data\n        have = list(obs["you"]["units"])\n        rival = list(obs["rival"]["units"])\n        base = int(obs["you"]["base"])\n        n = len(have)\n        remaining = max(0, N_TURNS - int(obs["turn"]))\n        # A rolling economic horizon avoids pretending that a drifting hotspot\n        # will persist unchanged for the entire match.\n        horizon = min(12, remaining)\n        want = [0] * n\n        if horizon == 0 or not obs.get("orders"):\n            return have\n\n        forecast = obs["orders"]\n        upkeep = [\n            0.0 if v == base else 1.0 + 0.5 * distances[base][v]\n            for v in range(n)\n        ]\n        previous = self.previous_want\n        if previous is None or len(previous) != n:\n            previous = have\n\n        # Marginal score-difference streams. Beyond the exact forecast, temper\n        # the final observation with the window mean rather than extrapolating\n        # short-lived growth indefinitely.\n        marginal = [[[] for _ in range(SERVE_LIMIT)] for _ in range(n)]\n        for v in range(n):\n            mean = sum(row[v] for row in forecast) / len(forecast)\n            for k in range(SERVE_LIMIT):\n                values = marginal[v][k]\n                for offset in range(horizon):\n                    if offset < len(forecast):\n                        demand = forecast[offset][v]\n                    else:\n                        blend = 0.92 ** (offset - len(forecast) + 1)\n                        demand = blend * forecast[-1][v] + (1.0 - blend) * mean\n                    values.append(\n                        margin_value(k + 1, rival[v], demand)\n                        - margin_value(k, rival[v], demand)\n                        - upkeep[v]\n                    )\n\n        # Paths charge upkeep after each move. An adjacent destination earns on\n        # offset 0; distance d therefore loses only d-1 earning turns.\n        travel = {}\n        for source in range(n):\n            if not have[source]:\n                continue\n            for target in range(n):\n                path_cost = 0.0\n                position = source\n                distance = distances[source][target]\n                if distance < 0:\n                    continue\n                for offset in range(min(max(0, distance - 1), horizon)):\n                    position = next_hop[position][target]\n                    path_cost += upkeep[position]\n                travel[source, target] = (\n                    max(0, distance - 1), path_cost\n                )\n\n        def return_value(source):\n            delay, cost = travel[source, base]\n            return -cost\n\n        baseline = {\n            source: return_value(source)\n            for source in range(n) if have[source]\n        }\n\n        def gain(source, target, k):\n            delay, cost = travel[source, target]\n            if delay >= horizon:\n                return -1e30\n            value = sum(marginal[target][k][delay:]) - cost\n            # Small hysteresis premiums apply to total trip value, not each\n            # earning turn, so genuinely better opportunities still win.\n            if k < previous[target]:\n                value += 1.1\n            if source == target and k < have[target]:\n                value += 0.7\n            return value - baseline[source]\n\n        available = list(have)\n        heap = []\n        for source in range(n):\n            if not available[source]:\n                continue\n            for target in range(n):\n                if target == base or (source, target) not in travel:\n                    continue\n                g = gain(source, target, 0)\n                heapq.heappush(heap, (-g, source, target, 0))\n\n        while heap and time.perf_counter() < deadline:\n            negative, source, target, version = heapq.heappop(heap)\n            if available[source] == 0 or want[target] >= SERVE_LIMIT:\n                continue\n            if version != want[target]:\n                k = want[target]\n                heapq.heappush(\n                    heap, (-gain(source, target, k), source, target, k)\n                )\n                continue\n            if negative >= -0.05:\n                break\n            available[source] -= 1\n            want[target] += 1\n            if available[source] and want[target] < SERVE_LIMIT:\n                k = want[target]\n                heapq.heappush(\n                    heap, (-gain(source, target, k), source, target, k)\n                )\n\n        want[base] += sum(available)\n        return want\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.6 * TIME_BUDGET)\n        if self.map_data is None:\n            self.map_data = preprocess_map(obs["graph"])\n\n        feedback = obs.get("feedback", {})\n        if not feedback.get("format_ok", True) or feedback.get("rejected", 0):\n            self.bad_reports += 1\n\n        have = list(obs["you"]["units"])\n        adjacency, distances, next_hop = self.map_data\n        if self.bad_reports >= 2:\n            # Conservative recovery: recall deployed units one hop toward home.\n            base = int(obs["you"]["base"])\n            want = [0] * len(have)\n            want[base] = sum(have)\n        else:\n            want = self.plan(obs, deadline)\n\n        action = legal_action(have, want, adjacency, distances, next_hop)\n        self.previous_want = list(want)\n        return action\n'
_CORE_CLASS = 'Strategy'
_FALLBACK_SRC = None
_FALLBACK_CLASS = 'Strategy'
